using Microsoft.Data.Sqlite;using System;using(var db=new SqliteConnection("Data Source=probe.sqlite")){db.Open();using var c=db.CreateCommand();c.CommandText="CREATE TABLE IF NOT EXISTS probe (value TEXT); INSERT INTO probe VALUES ('synthetic'); SELECT value FROM probe LIMIT 1";if((string)c.ExecuteScalar()!="synthetic")throw new Exception("SQLite probe failed");} Console.WriteLine("sqlite-ok");
